import re

_JOB_RE = re.compile(
    r"""
    JOB[ ](?P<name>\S+)
    [ ]AT[ ](?P<at>(?:[01][0-9]|2[0-3]):[0-5][0-9])
    [ ]RUN[ ](?P<script>\S+\.crms)
    (?:
        [ ]ON_ERROR[ ]
        (?:
            (?P<policy>ABORT|CONTINUE)
            |RETRY:(?P<retry>[0-9]+)
        )
    )?
    """,
    re.VERBOSE,
)


def parse_schedule(cfg_text: str) -> list[dict]:
    """Parse a Meridian CRM batch schedule while preserving file order."""
    schedule: list[dict] = []

    for line_number, raw_line in enumerate(cfg_text.splitlines(), start=1):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue

        match = _JOB_RE.fullmatch(line)
        if match is None:
            raise ValueError(f"invalid JOB line at line {line_number}: {raw_line!r}")

        policy = match.group("policy")
        retry = match.group("retry")

        if retry is not None:
            on_error = {"policy": "RETRY", "retries": int(retry)}
        else:
            on_error = {
                "policy": policy if policy is not None else "ABORT",
                "retries": 0,
            }

        schedule.append(
            {
                "name": match.group("name"),
                "at": match.group("at"),
                "script": match.group("script"),
                "on_error": on_error,
            }
        )

    return schedule
